1	package contractsentinel
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件锁定“归档读取”侧固定字段的大小写规则：报告标识、产物信息、每条
12	// 规则和缺陷记录中已经定义的字段，只认报告 JSON 中原有的大小写写法。
13	// encoding/json 在精确匹配失败后会退化为大小写不敏感匹配，因此一个名为
14	// "StAtus" 的扩展成员也会解码进 status 字段：它出现在原字段之后时会覆盖
15	// 真正的结论，出现在原字段之前时又能用合法值掩盖原字段里的非法值——同
16	// 一份归档仅因成员位置不同就得到不同读取结果。修正后，这些大小写变体与
17	// 两侧带空白的名字都只是被忽略的扩展字段，可信内容完全由固定字段决定。
18	
19	// statusByID 索引读出报告的规则结论。
20	func statusByID(r Report) map[string]string {
21		out := map[string]string{}
22		for _, rule := range r.Rules {
23			out[rule.ID] = rule.Status
24		}
25		return out
26	}
27	
28	// writeVariantArchiveText marshals a legal report with a fresh matching id,
29	// applies a textual mutation, then recomputes the report id from the fixed
30	// fields only and rewrites the reportId member to match. Extension members
31	// (case variants, unknown fields) stay in the archive text but do not
32	// influence the id, so any rejection comes from report validation itself,
33	// never from the id check.
34	func writeVariantArchiveText(t *testing.T, dir string, r Report, mutate func(string) string) string {
35		t.Helper()
36		r.ReportID = ReportID(r)
37		data, err := json.Marshal(r)
38		if err != nil {
39			t.Fatal(err)
40		}
41		doc := mutate(string(data))
42		if doc == string(data) {
43			t.Fatal("test setup: mutation did not change the archive")
44		}
45		strict, err := strictReportJSON([]byte(doc))
46		if err != nil {
47			t.Fatal(err)
48		}
49		var decoded Report
50		if err := json.Unmarshal(strict, &decoded); err != nil {
51			t.Fatal(err)
52		}
53		newID := ReportID(decoded)
54		doc = strings.Replace(doc, `"reportId":"`+r.ReportID+`"`, `"reportId":"`+newID+`"`, 1)
55		if err := os.WriteFile(filepath.Join(dir, newID+".json"), []byte(doc), 0o644); err != nil {
56			t.Fatal(err)
57		}
58		return newID
59	}
60	
61	// --- 核心场景：合法缺陷报告加入 StAtus 扩展字段，两种成员顺序读出同一结论 ---
62	
63	func TestLoadReportCaseVariantStatusDoesNotOverride(t *testing.T) {
64		for _, tc := range []struct {
65			name string
66			old  string
67			new  string
68		}{
69			{
70				name: "variant after fixed field",
71				old:  `"status":"` + StatusDefect + `"`,
72				new:  `"status":"` + StatusDefect + `","StAtus":"` + StatusPass + `"`,
73			},
74			{
75				name: "variant before fixed field",
76				old:  `"status":"` + StatusDefect + `"`,
77				new:  `"StAtus":"` + StatusPass + `","status":"` + StatusDefect + `"`,
78			},
79		} {
80			t.Run(tc.name, func(t *testing.T) {
81				dir := t.TempDir()
82				id := writeDupArchiveText(t, dir, oneDefectFixture(), dupOnce(tc.old, tc.new))
83	
84				loaded, err := LoadReport(dir, id)
85				if err != nil {
86					t.Fatalf("a case-variant extension member must not corrupt the report: %v", err)
87				}
88				if loaded.ReportID != id {
89					t.Fatalf("report id not preserved: %q", loaded.ReportID)
90				}
91				// 缺陷结论仍由原有 status 决定，不随扩展字段的位置变化。
92				if got := statusByID(loaded)["r-bad"]; got != StatusDefect {
93					t.Fatalf("r-bad status = %q, want the original %q", got, StatusDefect)
94				}
95				if got := statusByID(loaded)["r-pass"]; got != StatusPass {
96					t.Fatalf("r-pass status = %q, want %q", got, StatusPass)
97				}
98				// 说明、证据、产物哈希与规则版本原样保留。
99				rule := loaded.Rules[1]
100				if rule.ID != "r-bad" || rule.Note != "counterexample: x" || rule.Version != "2" {
101					t.Fatalf("rule not preserved: %+v", rule)
102				}
103				if len(loaded.Findings) != 1 {
104					t.Fatalf("findings = %d, want 1", len(loaded.Findings))
105				}
106				f := loaded.Findings[0]
107				if f.Evidence != "counterexample: x" || f.ArtifactHash != loaded.Artifact.Hash || f.Version != "2" {
108					t.Fatalf("finding not preserved: %+v", f)
109				}
110			})
111		}
112	}
113	
114	// --- 原字段写了不支持的状态，不能靠大小写变体提供合法状态来通过校验 ---
115	
116	func TestLoadReportCaseVariantCannotLaunderInvalidStatus(t *testing.T) {
117		dir := t.TempDir()
118		id := writeVariantArchiveText(t, dir, oneDefectFixture(),
119			dupOnce(`"status":"`+StatusPass+`"`,
120				`"status":"bogus","StAtus":"`+StatusPass+`"`))
121		expectCorruptLoad(t, dir, id, "r-pass")
122	}
123	
124	// --- 缺少原本的固定字段时，大小写变体不能替代该字段 ---
125	
126	func TestLoadReportCaseVariantCannotReplaceMissingStatus(t *testing.T) {
127		dir := t.TempDir()
128		id := writeVariantArchiveText(t, dir, oneDefectFixture(),
129			dupOnce(`"status":"`+StatusPass+`"`, `"StAtus":"`+StatusPass+`"`))
130		expectCorruptLoad(t, dir, id, "r-pass")
131	}
132	
