200	func TestCLIAuditPairedEscapeEqualsLiteralIdentity(t *testing.T) {
201		bin := auditBinary(t)
202		work := t.TempDir()
203	
204		// 同一逻辑 note：一次用 ASCII 代理对转义书写，一次直接写 UTF-8 字符。
205		hash := contractsentinelArtifactHashForCharset()
206		escDoc := charsetDefectDoc(hash, `"证据：\uD83D\uDE00 重入\n第二行  "`)
207		litDoc := charsetDefectDocLiteral(hash)
208	
209		escInput := writeInput(t, work, "esc.json", escDoc)
210		litInput := writeInput(t, work, "lit.json", litDoc)
211	
212		escOut, escErr, code := runCLIAudit(t, bin, escInput, filepath.Join(work, "store-esc"))
213		if code != 0 {
214			t.Fatalf("paired surrogate escape must be legal: %s", escErr)
215		}
216		litOut, litErr, code := runCLIAudit(t, bin, litInput, filepath.Join(work, "store-lit"))
217		if code != 0 {
218			t.Fatalf("literal character must be legal: %s", litErr)
219		}
220	
221		escReport := decodeReport(t, escOut)
222		litReport := decodeReport(t, litOut)
223		if escReport.Artifact.Hash != hash || litReport.Artifact.Hash != hash {
224			t.Fatalf("artifact hash must be the correctly-bound value:\nesc=%q\nlit=%q\nwant=%q",
225				escReport.Artifact.Hash, litReport.Artifact.Hash, hash)
226		}
227		if escReport.ReportID != litReport.ReportID {
228			t.Fatalf("report id differs between escaped and literal same-string forms:\n%s\n%s",
229				escReport.ReportID, litReport.ReportID)
230		}
231		wantNote := "证据：😀 重入\n第二行  "
232		if escReport.Findings[0].Evidence != wantNote || litReport.Findings[0].Evidence != wantNote {
233			t.Fatalf("evidence must preserve the decoded original text:\nesc=%q\nlit=%q\nwant=%q",
234				escReport.Findings[0].Evidence, litReport.Findings[0].Evidence, wantNote)
235		}
236		if !strings.Contains(escOut, "证据") {
237			t.Fatal("stdout report must carry the decoded CJK evidence text")
238		}
239	}
240	
241	// charsetDefectDocLiteral 与 charsetDefectDoc 内容相同，但 note 直接以
242	// UTF-8 书写 emoji 与换行转义。
243	func charsetDefectDocLiteral(hash string) string {
244		check := `{"artifactHash":"` + hash +
245			`","ruleId":"r1","version":"1.0.0","status":"发现缺陷","note":"证据：😀 重入\n第二行  "}`
246		return `{"artifact":` + charsetArtifactJSON + `,"rules":` + charsetRulesJSON + `,"checks":[` + check + `]}`
247	}
248	
249	// contractsentinelArtifactHashForCharset 计算 charsetArtifactJSON 对应产物
250	// 的内容哈希，避免测试手写哈希。
251	func contractsentinelArtifactHashForCharset() string {
252		return contractsentinel.ArtifactHash(contractsentinel.Artifact{
253			Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol",
254		})
255	}
