		`"status":"`+StatusPass+`"`,
		`"status":"`+StatusDefect+`","status":"`+StatusPass+`"`, 1)
	saveReportHook = func(string) {
		os.WriteFile(finalPath, []byte(dupDoc), 0o644)
	}
	defer func() { saveReportHook = nil }()

	err = SaveReport(dir, r)
