1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	
10		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
11	)
12	
13	// 本文件在真实命令行进程边界上回归保护 report / diff 读取已保存报告时对
14	// “重复 JSON 成员”的拒绝：归档任何对象（规则、缺陷记录、产物信息、顶层
15	// 对象及未知嵌套对象）重复同名成员，即使最后一个值使报告标识与缺陷归属
16	// 校验成立，也必须把整份报告判为归档损坏——非零退出、原因进 stderr（含
17	// 报告标识、成员名、所在对象；在规则/缺陷数组中给出位置与规则标识），
18	// stdout 不出现完整或部分报告，且原文件原样保留。
19	
20	// auditOneReport 通过真实 audit 命令落盘一份合法的混合状态报告，返回其标识。
21	func auditOneReport(t *testing.T, bin, work, store string) string {
22		t.Helper()
23		input := writeStructInput(t, work, "in.json", mixedCheckInput(mixedArtifactHash(t)))
24		stdout, stderr, code := runCLIAudit(t, bin, input, store)
25		if code != 0 {
26			t.Fatalf("setup audit must succeed: %s", stderr)
27		}
28		return decodeReport(t, stdout).ReportID
29	}
30	
31	// injectArchiveDuplicate reads the archive named by id, applies the textual
32	// replacement once, and writes it back. All replacements repeat a member
33	// while leaving the last value identical to the legal one.
34	func injectArchiveDuplicate(t *testing.T, store, id, old, new string) {
35		t.Helper()
36		path := filepath.Join(store, id+".json")
37		data, err := os.ReadFile(path)
